/**
 * Private file storage. Photos and documents are never public. Access is granted only by the
 * application after an authorisation check. Keys are generated by the server, never taken from users.
 */
export interface FileStore {
  put(key: string, data: Uint8Array<ArrayBuffer>, mime: string): Promise<void>;
  get(key: string): Promise<Uint8Array<ArrayBuffer> | null>;
  delete(key: string): Promise<void>;
}

/** The subset of the Cloudflare R2 binding API used here. */
export interface R2Like {
  put(key: string, value: Uint8Array<ArrayBuffer>, options?: { httpMetadata?: { contentType?: string } }): Promise<unknown>;
  get(key: string): Promise<{ arrayBuffer(): Promise<ArrayBuffer> } | null>;
  delete(key: string): Promise<void>;
}

/** Cloudflare R2 private bucket (no public access, no custom domain). */
export function r2Files(bucket: R2Like): FileStore {
  return {
    async put(key, data, mime) {
      await bucket.put(key, data, { httpMetadata: { contentType: mime } });
    },
    async get(key) {
      const object = await bucket.get(key);
      return object ? new Uint8Array(await object.arrayBuffer()) : null;
    },
    async delete(key) {
      await bucket.delete(key);
    },
  };
}
